import streamlit as st
from collections import deque

st.title('Calculator App')

# Initialize history in session state
if 'history' not in st.session_state:
    st.session_state.history = deque(maxlen=10)

col1, col2 = st.columns(2)

with col1:
    num1 = st.number_input('First number', value=0.0)
    operator = st.selectbox('Operator', ['+', '-', '*', '/'])
    num2 = st.number_input('Second number', value=0.0)

    if st.button('Calculate'):
        try:
            ops = {
                '+': num1 + num2,
                '-': num1 - num2,
                '*': num1 * num2,
                '/': num1 / num2 if num2 != 0 else None,
            }
            result = ops[operator]
            if result is None:
                st.error('Cannot divide by zero!')
            else:
                st.success(f'Result: {result}')
                st.session_state.history.append(
                    f'{num1} {operator} {num2} = {result}'
                )
        except Exception as e:
            st.error(f'Error: {e}')

with col2:
    st.subheader('History')
    if st.button('Clear History'):
        st.session_state.history.clear()
    for entry in reversed(st.session_state.history):
        st.text(entry)

import streamlit as st
import uuid
from datetime import datetime

st.title('Note Taking App')

# Initialize state
if 'notes' not in st.session_state:
    st.session_state.notes = [{
        'id': str(uuid.uuid4()), 'title': 'Welcome',
        'body': 'This is your first note. Edit or delete it, or create new ones!',
        'created_at': datetime.now().isoformat(),
        'updated_at': datetime.now().isoformat(),
    }]
if 'selected_id' not in st.session_state:
    st.session_state.selected_id = st.session_state.notes[0]['id'] if st.session_state.notes else None
if 'mode' not in st.session_state:
    st.session_state.mode = 'view'

def find_note(note_id):
    return next((n for n in st.session_state.notes if n['id'] == note_id), None)

# Sidebar
search = st.sidebar.text_input('Search notes', placeholder='Type to search...')
if st.sidebar.button('📝 New Note'):
    st.session_state.mode = 'create'
    st.session_state.selected_id = None

filtered = [n for n in st.session_state.notes
            if not search or search.lower() in n['title'].lower()
            or search.lower() in n['body'].lower()]
for note in filtered:
    if st.sidebar.button(note['title'], key=f"note_{note['id']}"):
        st.session_state.selected_id = note['id']
        st.session_state.mode = 'view'
        st.rerun()

# Main area
if st.session_state.mode == 'create':
    st.subheader('Create New Note')
    title = st.text_input('Title')
    body = st.text_area('Content', height=300)
    c1, c2 = st.columns(2)
    if c1.button('Save') and title:
        new_note = {'id': str(uuid.uuid4()), 'title': title, 'body': body,
                    'created_at': datetime.now().isoformat(),
                    'updated_at': datetime.now().isoformat()}
        st.session_state.notes.insert(0, new_note)
        st.session_state.selected_id = new_note['id']
        st.session_state.mode = 'view'
        st.rerun()
    if c2.button('Cancel'):
        st.session_state.mode = 'view'
        st.rerun()

elif st.session_state.selected_id:
    note = find_note(st.session_state.selected_id)
    if note:
        if st.session_state.mode == 'view':
            st.subheader(note['title'])
            st.write(note['body'])
            st.caption(f"Created: {note['created_at']} | Updated: {note['updated_at']}")
            c1, c2 = st.columns(2)
            if c1.button('Edit'):
                st.session_state.mode = 'edit'
                st.rerun()
            if c2.button('Delete'):
                st.session_state.notes = [n for n in st.session_state.notes if n['id'] != note['id']]
                st.session_state.selected_id = st.session_state.notes[0]['id'] if st.session_state.notes else None
                st.rerun()
        elif st.session_state.mode == 'edit':
            st.subheader('Edit Note')
            title = st.text_input('Title', value=note['title'])
            body = st.text_area('Content', value=note['body'], height=300)
            c1, c2 = st.columns(2)
            if c1.button('Save'):
                note['title'] = title
                note['body'] = body
                note['updated_at'] = datetime.now().isoformat()
                st.session_state.mode = 'view'
                st.rerun()
            if c2.button('Cancel'):
                st.session_state.mode = 'view'
                st.rerun()

else:
    st.info('Select a note from the sidebar or create a new one.')
